    words,
    { opacity: [0, 1], y: [28, 0], filter: ["blur(8px)", "blur(0px)"] },
    {
      duration: 0.7,
      delay: stagger(0.07, { startDelay: 0.25 }),
      ease: [0.22, 1, 0.36, 1],
    },
  );
  animate(
    rest,
