      row-gap: 17px;
      align-items: baseline;
    }
    .meta-grid > :global(dt:not(:first-child)) {
      margin-top: 0;
    }
  }
  .meta-label {
    font-family: var(--font-mono);
    font-size: 14px;
    text-transform: uppercase;
    color: var(--portfolio-muted);
  }
  .meta-value {
    margin: 0;
    font-family: var(--font-mono);
    font-size: 14px;
    text-transform: uppercase;
    color: var(--portfolio-ink);
  }
  /* Scope is a longer run of text: 24px line height, wrapping in the value column. */
  .meta-value--wrap {
    line-height: 24px;
  }
  /* The chips: 15% project-color fill, 8px/3px padding, 4px corners. */
  .meta-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 3px 8px;
    border-radius: 4px;
    background-color: color-mix(in srgb, var(--icon-color) 15%, transparent);
    color: var(--portfolio-ink);
    font-family: var(--font-mono);
    font-size: 14px;
    font-weight: 500;
  }
  .meta-badge :global(svg) {
    color: var(--icon-color);
  }
