content.content:
const { art } = Astro.props;

// width/height: the space the artwork takes in the layout (its design size).
// innerHeight: the artwork's own height when it differs, e.g. the CPU card is
// 275px tall but only 209px of that counts toward the layout, because the
// headline overlaps the rest. `phone` is the scale used on small screens.
const specs = {
  toasts: {
    width: 465.772,
    height: 181.192,
    innerHeight: 181.192,
    phone: 0.68,
  },
  mark: { width: 202.647, height: 201.808, innerHeight: 201.808, phone: 0.6 },
  "cpu-card": {
    width: 597.927,
    height: 208.987,
    innerHeight: 274.987,
    phone: 0.5,
  },
} as const;

const spec = art ? specs[art] : null;
---

{
  spec && (
    <div
      class="hero-art"
      style={`--w:${spec.width}px;--h:${spec.height}px;--ih:${spec.innerHeight}px;--phone:${spec.phone};`}
    >
      <div class="hero-art-inner" data-ov="art">
        {art === "toasts" && <PingToasts />}
        {art === "mark" && <UndercurrentMark />}
        {art === "cpu-card" && <WatchtowerCpuCard />}
      </div>
    </div>

