---
// Overview.astro — the case study's opening "presentation" (Figma: the
// "Project — Detail" frames). From top to bottom:
//   1. a centered hero: per-project artwork, an oversized headline with the
//      accent phrase in the project color, and a small project chip
//   2. the description
//   3. a two-column row: an action menu (Read deep dive / Watch walkthrough /
//      View gallery) on the left, the project's type, role and scope on the right
//
// The menu items are real buttons with keyboard shortcuts (Enter / W / G), so
// they don't need entries in the bottom nav. The `data-ov` attributes are hooks
// for the entrance animation in src/lib/caseStudy.ts (built with Motion).
import type { ComponentType, SVGProps } from "react";
import { Play } from "pixelarticons/react/Play";
import ActionButton from "@/components/ActionButton.astro";
import HeroArt from "@/components/case-study/hero/HeroArt.astro";
import { slashList, typeIcon } from "@/lib/projectMeta";

interface Props {
  name: string;
  tagline: string;
  accentPhrase?: string;
  description?: string;
  icon: ComponentType<SVGProps<SVGSVGElement>>;
  heroArt?: "toasts" | "mark" | "cpu-card";
  type?: string;
  role?: string;
  scope?: string;
  hasWalkthrough?: boolean;
  hasGallery?: boolean;
}

const {
  name,
  tagline,
  accentPhrase,
  description,
  icon: Icon,
  heroArt,
  type,
  role,
  scope,
  hasWalkthrough,
  hasGallery,
} = Astro.props;

const TypeIcon = type ? typeIcon(type) : null;

// Split the headline into words (so each can animate in on its own), marking
// the words that fall inside the accent phrase.
const accentStart = accentPhrase ? tagline.indexOf(accentPhrase) : -1;
const accentEnd =
  accentStart >= 0 ? accentStart + (accentPhrase?.length ?? 0) : -1;
let cursor = 0;
const words = tagline.split(" ").map((text) => {
  const start = cursor;
  cursor += text.length + 1;
  const accent = accentStart >= 0 && start >= accentStart && start < accentEnd;
  return { text, accent };
});
---

<div class="overview">
  <div class="hero">
    <HeroArt art={heroArt} />

    <div class="hero-title">
      <h1 class="overview-headline m-0">
        {
          words.map(({ text, accent }) => (
            <span
              data-ov="word"
              class:list={["inline-block", accent && "italic"]}
              style={accent ? "color: var(--icon-color);" : undefined}
            >
              {text}&nbsp;
            </span>
          ))
        }
      </h1>

      <div data-ov="name" class="project-chip">
        <span class="chip-tile">
          <Icon width={15} height={15} />
        </span>
        <span class="chip-name">{name}</span>
      </div>
    </div>
  </div>

  <div class="overview-body">
    {
      description && (
        <p data-ov="desc" class="overview-description">
          {description}
        </p>
      )
    }

    <div data-ov="meta" class="overview-row">
      <div class="action-menu">
        <ActionButton
          block
          featured
          label="Read deep dive"
          shortcut="enter"
          href="#deep-dive"
        />
        {
          hasWalkthrough && (
            <ActionButton
              block
              label="Watch walkthrough"
              shortcut="w"
              href="#walkthrough"
            />
          )
        }
        {
          hasGallery && (
            <ActionButton
              block
              label="View gallery"
              shortcut="g"
              href="#gallery"
            />
          )
        }
      </div>

      <div class="overview-details">
        <div class="chip-row">
          {
            type && TypeIcon && (
              <span class="meta-badge">
                <TypeIcon width={16} height={16} />
                {type}
              </span>
            )
          }
          {
            hasWalkthrough && (
              <span class="meta-badge">
                <Play width={14} height={14} />
                Video walkthrough
              </span>
            )
          }
        </div>
        {
          role && (
            <div class="detail">
              <p class="detail-label">Role</p>
              <p class="detail-value">{slashList(role)}</p>
            </div>
          )
        }
        {
          scope && (
            <div class="detail">
              <p class="detail-label">Scope</p>
              <p class="detail-value detail-value--wrap">{slashList(scope)}</p>
            </div>
          )
        }
      </div>
    </div>
  </div>
</div>

<style>
  .overview {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 80px;
    width: 100%;
  }

  /* ─── Hero ─────────────────────────────────────────────────────────────── */
  .hero {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    max-width: 888px;
  }
  .hero-title {
    position: relative; /* so the headline can sit over a CPU card behind it */
    z-index: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 48px;
    width: 100%;
  }
  /* Redaction 35 at 72px, 0.94 line height, -2.16px tracking, centered. */
  .overview-headline {
    max-width: 888px;
    text-align: center;
    font-family: var(--font-redaction);
    font-size: clamp(2.75rem, 1.2rem + 4.8vw, 4.5rem);
    font-weight: 400;
    line-height: 0.9444; /* 68px at 72px: two lines are 136px tall, as in Figma */
    letter-spacing: -0.03em;
    color: var(--portfolio-ink);
  }

  /* "Project Ping": a 24px tile in the project's tint, then the name. */
  .project-chip {
    display: flex;
    align-items: center;
    gap: 12.8px;
  }
  .chip-tile {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    border-radius: 6px;
    background-color: color-mix(in srgb, var(--icon-color) 15%, transparent);
    color: var(--icon-color);
  }
  .chip-name {
    font-family: var(--font-mono);
    font-size: 16px;
    line-height: 1.4;
    letter-spacing: -0.16px;
    color: var(--portfolio-ink);
  }

  /* ─── Body ─────────────────────────────────────────────────────────────── */
  .overview-body {
    display: flex;
    flex-direction: column;
    gap: 40px;
    width: 100%;
    max-width: 900px;
  }
  .overview-description {
    margin: 0;
    font-family: var(--font-plex-sans);
    font-size: 18px;
    line-height: 28px;
    color: color-mix(in srgb, var(--portfolio-ink) 85%, transparent);
  }
  /* Stacked on small screens; side by side (360px menu, 80px gap) from lg. */
  .overview-row {
    display: flex;
    flex-direction: column;
    gap: 40px;
  }
  @media (min-width: 64rem) {
    .overview-row {
      flex-direction: row;
      gap: 80px;
    }
    .action-menu {
      flex: none;
      width: 360px;
    }
    .overview-details {
      flex: 1 1 0;
      min-width: 0;
    }
  }
  .action-menu {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  /* ─── Details ──────────────────────────────────────────────────────────── */
  .overview-details {
    display: flex;
    flex-direction: column;
    gap: 22px;
  }
  .chip-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }
  /* The same chips as the Projects page: project tint, 4px corners. */
  .meta-badge {
    display: flex;
    width: fit-content;
    align-items: center;
    gap: 6px;
    padding: 3px 8px;
    border-radius: 4px;
    background-color: color-mix(in srgb, var(--icon-color) 15%, transparent);
    color: var(--portfolio-ink);
    font-family: var(--font-mono);
    font-size: 14px;
    font-weight: 500;
    line-height: normal;
  }
  .meta-badge :global(svg) {
    color: var(--icon-color);
  }
  /* A label stacked over its value, 8px apart. */
  .detail {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .detail-label,
  .detail-value {
    margin: 0;
    font-family: var(--font-mono);
    font-size: 14px;
    line-height: normal;
    text-transform: uppercase;
  }
  .detail-label {
    color: var(--portfolio-muted);
  }
  .detail-value {
    color: var(--portfolio-ink);
  }
  .detail-value--wrap {
    line-height: 24px;
  }
</style>

---
// HeroArt.astro — picks the Overview's artwork for a project (see `heroArt` in
// the projects collection) and sizes it. Each artwork has a fixed design size,
// taken from Figma; below the lg breakpoint it's scaled down as a whole so it
// fits narrow screens.
import PingToasts from "@/components/case-study/hero/PingToasts.astro";
import UndercurrentMark from "@/components/case-study/hero/UndercurrentMark.astro";
import WatchtowerCpuCard from "@/components/case-study/hero/WatchtowerCpuCard.astro";

interface Props {
  art?: "toasts" | "mark" | "cpu-card";
}

const { art } = Astro.props;

// width/height: the space the artwork takes in the layout (its design size).
// innerHeight: the artwork's own height when it differs, e.g. the CPU card is
// 275px tall but only 209px of that counts toward the layout, because the
// headline overlaps the rest. `gap` is the space between the artwork and the
// headline (0 for the CPU card, which is meant to sit behind it). `phone` is the
// scale used on small screens.
const specs = {
  toasts: {
    width: 465.772,
    height: 181.192,
    innerHeight: 181.192,
    gap: 64,
    phone: 0.68,
  },
  mark: {
    width: 202.647,
    height: 201.808,
    innerHeight: 201.808,
    gap: 64,
    phone: 0.6,
  },
  "cpu-card": {
    width: 597.927,
    height: 208.987,
    innerHeight: 274.987,
    gap: 0,
    phone: 0.5,
  },
} as const;

const spec = art ? specs[art] : null;
---

{
  spec && (
    <div
      class="hero-art"
      data-ov="art"
      style={`--w:${spec.width}px;--h:${spec.height}px;--ih:${spec.innerHeight}px;--gap:${spec.gap}px;--phone:${spec.phone};`}
    >
      <div class="hero-art-inner">
        {art === "toasts" && <PingToasts />}
        {art === "mark" && <UndercurrentMark />}
        {art === "cpu-card" && <WatchtowerCpuCard />}
      </div>
    </div>
  )
}

<style>
  /* The wrapper reserves the scaled space; the inner box keeps the artwork's
     design size and is scaled from its top-center. */
  .hero-art {
    --s: 1;
    position: relative;
    width: calc(var(--w) * var(--s));
    height: calc(var(--h) * var(--s));
    margin-bottom: calc(var(--gap) * var(--s));
    flex: none;
  }
  .hero-art-inner {
    position: absolute;
    top: 0;
    left: 0;
    width: var(--w);
    height: var(--ih);
    transform: scale(var(--s));
    transform-origin: top left;
  }
  @media (max-width: 63.99rem) {
    .hero-art {
      --s: calc(var(--phone) + (1 - var(--phone)) * 0.5);
    }
  }
  @media (max-width: 39.99rem) {
    .hero-art {
      --s: var(--phone);
    }
  }
</style>

{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "astro-dev",
      "runtimeExecutable": "bun",
      "runtimeArgs": ["run", "dev", "--", "--port", "4400"],
      "port": 4400
    }
  ]
}

---
// ActionButton.astro — the "secondary" button from Figma's "New buttons"
// section: transparent at rest, and on hover/focus it fills with the theme's
// ink color (text flips to the page color) and lifts with the shared
// --media-frame-shadow. A small key-cap tile on the left tells the visitor
// which keyboard key triggers the same action.
//
// Renders an <a> when `href` is given, otherwise a <button>.
//
// Keyboard shortcuts: pass `shortcut`. We stamp it on the element as
// `data-shortcut`, and the single global listener in src/lib/shortcuts.ts
// finds the element and clicks it. That means a page never wires up key
// handlers itself — it only declares buttons.
import { ArrowReturnLeft } from "pixelarticons/react/ArrowReturnLeft";

interface Props {
  label: string;
  // Shorter text used instead of `label` below the sm breakpoint, where space
  // is tight (e.g. "Walkthrough" for "Watch walkthrough").
  shortLabel?: string;
  // Dimmed text after the label, e.g. the next project's name.
  detail?: string;
  // "enter" and "esc" get their special glyphs; anything else is shown as an
  // uppercase single character (e.g. "x", "w").
  shortcut?: "enter" | "esc" | (string & {});
  href?: string;
  // Pill shape (Start page) vs. the slightly squarer bottom-nav shape.
  shape?: "pill" | "rounded";
  // Always-filled look (the same as hover), for the page's primary action.
  featured?: boolean;
  // The large, full-width "menu item" form used in the case-study Overview:
  // 18px text, a pill with 16px/12px padding, label on the left and the key
  // tile pushed to the far right.
  block?: boolean;
  hidden?: boolean;
  class?: string;
  id?: string;
  [key: `data-${string}`]: string | boolean | undefined;
}

const {
  label,
  shortLabel,
  detail,
  shortcut,
  href,
  shape = "rounded",
  featured = false,
  block = false,
  class: className,
  id,
  ...rest
} = Astro.props;

const Tag = href ? "a" : "button";
const keyName = shortcut?.toLowerCase();
---

<Tag
  id={id}
  href={href}
  type={href ? undefined : "button"}
  data-shortcut={keyName}
  class:list={[
    "action-button text-portfolio-ink inline-flex shrink-0 cursor-pointer items-center font-mono whitespace-nowrap",
    block
      ? // Large menu item: 360px-ish pill, label left, key tile right. Only the
        // filled primary item is medium weight and full-strength ink; the rest are
        // regular weight at 80% ink.
        [
          "w-full justify-between gap-3 rounded-full px-4 py-3 text-lg leading-[normal]",
          featured ? "font-medium" : "text-portfolio-ink/80 font-normal",
        ]
      : [
          "text-base font-medium",
          // Figma: the filled (primary) look is 12px/8px padding with a 4px icon
          // gap; the plain secondary look is 8px padding with a 12px gap.
          featured ? "gap-1 px-3 py-2" : "gap-3 p-2",
          // Corners: fully round for the pill shape, otherwise 8px.
          shape === "pill" ? "rounded-full" : "rounded-md",
        ],
    featured && "is-featured",
    block && "is-block",
    className,
  ]}
  {...rest}
>
  {
    shortcut && (
      <span
        aria-hidden="true"
        class:list={[
          "keycap bg-portfolio-keycap flex h-6 items-center justify-center rounded-sm",
          // In the block form the key tile sits at the far right, after the label.
          block && "order-last",
          // ESC is three letters wide; every other key is a square tile.
          keyName === "esc" ? "w-10 text-xs tracking-wider" : "w-6",
        ]}
      >
        {keyName === "enter" ? (
          <ArrowReturnLeft width={18} height={18} />
        ) : keyName === "esc" ? (
          "ESC"
        ) : (
          <span class="text-sm">{keyName?.toUpperCase()}</span>
        )}
      </span>
    )
  }
  <span>
    {
      shortLabel ? (
        <>
          <span class="max-sm:hidden">{label}</span>
          <span class="sm:hidden">{shortLabel}</span>
        </>
      ) : (
        label
      )
    }
    {detail && <span class="text-portfolio-muted"> {detail}</span>}
  </span>
</Tag>

<style>
  .action-button {
    background-color: transparent;
    box-shadow: none;
    /* The transition lives on the resting selector, not :active, so it plays
       on press AND on release. */
    transition:
      transform 0.15s ease-out,
      box-shadow 0.15s ease-out,
      background-color 0.15s ease-out,
      color 0.15s ease-out;
  }

  /* Browsers show the default focus ring on some mouse clicks (Safari); we
     only want a ring for keyboard focus, and hover/focus-visible already
     share the filled look below. */
  .action-button:focus {
    outline: none;
  }

  .action-button:hover,
  .action-button:focus-visible,
  .action-button.is-featured {
    background-color: var(--portfolio-ink);
    color: var(--portfolio-bg);
    box-shadow: var(--media-frame-shadow);
  }

  /* While the button is filled with ink, the key-cap and the dimmed detail
     text need to follow the inverted colors, or they'd vanish. */
  .action-button:hover :global(.bg-portfolio-keycap),
  .action-button:focus-visible :global(.bg-portfolio-keycap) {
    background-color: color-mix(in srgb, var(--portfolio-bg) 18%, transparent);
  }
  /* On the always-filled primary look Figma shows the arrow directly on the
     fill, with no tile behind it. */
  .action-button.is-featured :global(.bg-portfolio-keycap) {
    background-color: transparent;
  }
  .action-button:hover :global(.text-portfolio-muted),
  .action-button:focus-visible :global(.text-portfolio-muted),
  .action-button.is-featured :global(.text-portfolio-muted) {
    color: color-mix(in srgb, var(--portfolio-bg) 55%, transparent);
  }

  /* "Depress on click": shrink slightly and collapse the shadow so the
     button sinks toward the page. */
  .action-button:active {
    transform: scale(0.97);
    box-shadow: var(--button-shadow-pressed);
  }

  /* No keyboard to show shortcuts for: on touch devices and very narrow
     screens the key-cap is dropped (the action still works by tapping), and
     the button gets a little more side padding so the label doesn't crowd. */
  @media (hover: none), (max-width: 39.99rem) {
    .action-button :global(.keycap) {
      display: none;
    }
    /* The compact bottom-nav buttons shrink; the large Overview menu items keep
       their size. */
    .action-button:not(.is-block) {
      gap: 0;
      padding: 0.5rem 0.75rem;
      font-size: 0.875rem;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .action-button {
      transition: none;
    }
    .action-button:active {
      transform: none;
    }
  }
</style>

