content.content:
1	---
2	// ProjectLayout.astro — wraps an individual project's case-study page.
3	//
4	// A case study is one page made of four full-screen sections the reader
5	// scrolls through, with CSS scroll-snap aligning each to the top of the
6	// screen:
7	//   Overview     — an oversized title-slide presentation (Overview.astro)
8	//   Deep dive    — the write-up: the MDX body passed in through <slot />
9	//   Walkthrough  — the Loom recording (Walkthrough.astro)
10	//   Gallery      — every still and loop in one grid (Gallery.astro)
11	// A side nav (SubNav.astro) tracks the current section, and the bottom nav
12	// swaps its actions per section. The scroll-tracking lives in
13	// src/lib/caseStudy.ts.
14	import BaseLayout from "@/layouts/BaseLayout.astro";
15	import Lightbox from "@/components/Lightbox.astro";
16	import SubNav from "@/components/case-study/SubNav.astro";
17	import Overview from "@/components/case-study/Overview.astro";
18	import Walkthrough from "@/components/case-study/Walkthrough.astro";
19	import Gallery from "@/components/case-study/Gallery.astro";
20	import MobileSectionBar from "@/components/MobileSectionBar.astro";
21	import type { NavAction } from "@/layouts/BottomNav.astro";
22	import type { ComponentType, SVGProps } from "react";
23	
24	interface GalleryItem {
25	  kind: "image" | "video";
26	  src?: string;
27	  webm?: string;
28	  mp4?: string;
29	  alt: string;
30	  label: string;
31	  caption: string;
32	}
33	
34	interface Props {
35	  slug: string;
36	  name: string;
37	  tagline: string;
38	  icon: ComponentType<SVGProps<SVGSVGElement>>;
39	  iconColor?: string;
40	  iconColorDark?: string;
41	  badgeColor?: string;
42	  badgeColorDark?: string;
43	  description?: string;
44	  accentPhrase?: string;
45	  loomUrl?: string;
46	  role?: string;
47	  scope?: string;
48	  type?: string;
49	  heroArt?: "toasts" | "mark" | "cpu-card";
50	  gallery?: GalleryItem[];
51	  // The project the "Next project" action leads to (wraps around to the first).
52	  next?: { slug: string; name: string };
53	}
54	
55	const {
56	  slug,
57	  name,
58	  tagline,
59	  icon,
60	  iconColor,
61	  iconColorDark,
62	  badgeColor,
63	  badgeColorDark,
64	  description,
65	  accentPhrase,
66	  loomUrl,
67	  role,
68	  scope,
69	  type,
70	  heroArt,
71	  gallery = [],
72	  next,
73	} = Astro.props;
74	
75	const hasWalkthrough = Boolean(loomUrl);
76	const hasGallery = gallery.length > 0;
77	
78	// Per-project colors as inline custom properties on the page root; global.css
79	// resolves them to --icon-color / --badge-color for the active theme, and every
80	// section below inherits them.
81	const colorVars = {
82	  ...(iconColor ? { "--icon-color-light": iconColor } : {}),
83	  ...(iconColorDark ? { "--icon-color-dark": iconColorDark } : {}),
84	  ...(badgeColor ? { "--badge-color-light": badgeColor } : {}),
85	  ...(badgeColorDark ? { "--badge-color-dark": badgeColorDark } : {}),
86	};
87	
88	// Chips for the small-screen section bar (top-level sections only; the side
89	// nav's Deep dive sub-items are desktop-only).
90	const sectionChips = [
91	  { id: "overview", label: "Overview" },
92	  { id: "deep-dive", label: "Deep dive" },
93	  ...(hasWalkthrough ? [{ id: "walkthrough", label: "Walkthrough" }] : []),
94	  ...(hasGallery ? [{ id: "gallery", label: "Gallery" }] : []),
95	];
96	
97	// Loom share URLs (loom.com/share/<id>) don't render embedded — the player
98	// requires the /embed/<id> path. Only needed here for the preconnect hints.
99	const embedSrc = loomUrl?.replace("/share/", "/embed/");
100	
101	// Bottom-nav actions: Next project (X) and Back (Esc, to the project's home
102	// preview), the same in every section. The Overview's own "Read deep dive /
103	// Watch walkthrough / View gallery" actions are buttons inside that section.
104	const actions: NavAction[] = [
105	  ...(next
106	    ? [
107	        {
108	          label: "Next project",
109	          detail: next.name.replace(/^Project\s+/, ""),
110	          shortcut: "x",
111	          href: `/projects/${next.slug}`,
112	        },
113	      ]
114	    : []),
115	  { label: "Back", shortcut: "esc", href: `/home/${slug}` },
116	];
117	---
118	
119	<BaseLayout
120	  page="case-study"
121	  section="overview"
122	  title={name}
123	  description={tagline}
124	  actions={actions}
125	>
126	  {
127	    /* Warms up the connection to Loom's domains as soon as the page loads,
128	      instead of paying full DNS+TLS+redirect latency when the reader scrolls
129	      to the walkthrough. Rendered into BaseLayout's named "head" slot — a
130	      link in the default slot stays in the body where it's written, it isn't
131	      auto-hoisted to the head the way style and script tags are. */
132	  }
133	  {
134	    embedSrc && (
135	      <Fragment slot="head">
136	        <link rel="preconnect" href="https://www.loom.com" />
137	        <link rel="preconnect" href="https://cdn.loom.com" crossorigin />
138	      </Fragment>
139	    )
140	  }
141	
142	  <div
143	    data-case-study
144	    style={colorVars}
145	    class="mx-auto -mt-20 w-full max-w-[1248px] px-6 lg:grid lg:grid-cols-[260px_minmax(0,900px)] lg:gap-10"
146	  >
147	    <!-- The -mt-20 pulls this up by the sticky header's height (h-20), so the
148	         Overview starts at the very top of the page and its snap point is
149	         scroll position 0, with the header floating over it. -->
150	    <!-- Side nav: sticky so it stays put while the sections scroll past.
151	         Hidden on narrow screens for now (small-screen pass comes later). -->
152	    <!-- It fades away on the Overview, which is a full-width presentation. -->
153	    <aside data-subnav-aside class="hidden lg:block">
154	      <div class="sticky top-32">
155	        <SubNav hasWalkthrough={hasWalkthrough} hasGallery={hasGallery} />
156	      </div>
157	    </aside>
158	
159	    <div class="min-w-0">
160	      <MobileSectionBar items={sectionChips} navAttr="data-subnav-mobile" />
161	      <section
162	        id="overview"
163	        data-section="overview"
164	        class="case-section case-section--overview"
165	      >
166	        <Overview
167	          name={name}
168	          tagline={tagline}
169	          accentPhrase={accentPhrase}
170	          description={description ?? tagline}
171	          icon={icon}
172	          heroArt={heroArt}
173	          type={type}
174	          role={role}
175	          scope={scope}
176	          hasWalkthrough={hasWalkthrough}
177	          hasGallery={hasGallery}
178	        />
179	      </section>
180	
181	      <section id="deep-dive" data-section="deep-dive" class="case-section">
182	        {
183	          /* The write-up. `.article-body` carries the MDX typography and the
184	          .ping-section* card styles below. */
185	        }
186	        <div
187	          class="article-body font-plex-sans text-portfolio-ink text-base leading-8"
188	        >
189	          <slot />
190	        </div>
191	      </section>
192	
193	      {
194	        loomUrl && (
195	          <section
196	            id="walkthrough"
197	            data-section="walkthrough"
198	            class="case-section flex items-center"
199	          >
200	            <Walkthrough loomUrl={loomUrl} name={name} />
201	          </section>
202	        )
203	      }
204	
205	      {
206	        hasGallery && (
207	          <section id="gallery" data-section="gallery" class="case-section">
208	            <Gallery items={gallery} />
209	          </section>
210	        )
211	      }
212	    </div>
213	  </div>
214	
215	  <Lightbox />
216	</BaseLayout>
217	
218	<script>
219	  import { observeGridReveal } from "@/lib/animations";
220	  import { initCaseStudy } from "@/lib/caseStudy";
221	
222	  // Runs on first load and after every client-side navigation, so each case
223	  // study you open re-binds scroll tracking, replays the Overview entrance, and
224	  // animates the "Approach" dot grid.
225	  document.addEventListener("astro:page-load", () => {
226	    initCaseStudy();
227	    observeGridReveal();
228	  });
229	</script>
230	
231	<style>
232	  /* MDX content comes from a separately-compiled component tree (rendered via
233	     <Content /> in [slug].astro), so Astro's default *scoped* styles never
234	     attach to it — every rule here needs :global() or it silently does nothing. */
235	  /* Two separate spacing tokens, easy to conflate but serving different
236	     jobs:
237	       --ping-section-gap   — vertical rhythm BETWEEN sections. Stays a
238	                               fixed 60px at every viewport width — this is
239	                               breathing room in the reading flow, not
240	                               something that should compress on mobile.
241	       --ping-card-padding   — the INSET inside a bordered/gradient card
242	                               (Problem/Approach/Solution) and the
243	                               <article> wrapper's own horizontal margin.
244	                               This one DOES scale down on narrow screens
245	                               (24px mobile / 40px tablet / 60px desktop,
246	                               matching <article>'s own
247	                               px-6 sm:px-10 lg:px-[60px]) — a flat 60px
248	                               inset squished the readable column badly on
249	                               phones. Collapsing both into one variable
250	                               previously made the inter-section gap shrink
251	                               along with the card padding, which read as
252	                               sections crowding each other on mobile. */
253	  .article-body {
254	    --ping-section-gap: 3.75rem; /* 60px, fixed at every width */
255	    --ping-card-padding: 1.5rem; /* 24px */
256	  }
257	
258	  @media (min-width: 40rem) {
259	    .article-body {
260	      --ping-card-padding: 2.5rem; /* 40px */
261	    }
262	  }
263	
264	  @media (min-width: 64rem) {
265	    .article-body {
266	      --ping-card-padding: 3.75rem; /* 60px */
267	    }
268	  }
269	
270	  /* Each top-level block in the MDX body is wrapped in its own
271	     `.ping-section`, so this gap can sit on both sides of a section as
272	     real padding (padding needs a real box on each edge — a
273	     margin-collapse-via-adjacency-selector approach only works for a flat
274	     list of siblings, and margin between siblings COLLAPSES rather than
275	     stacking, which reads as inconsistent spacing once some sections also
276	     have their own border/background — a card's edge should have a
277	     definite, non-collapsing gap around it). The first section only gets
278	     bottom padding, matching Figma's Intro frame using pb-[60px] instead
279	     of py-[60px] since there's nothing above it to pad against.
280	     Problem/Approach/Solution below add their own padding-LEFT/RIGHT only
281	     (not the `padding` shorthand) — the shorthand would overwrite this
282	     rule's padding-top/-bottom outright, since both rules have equal
283	     specificity and the later one wins on every side it touches. Setting
284	     only the two horizontal longhands here means their own left/right
285	     inset composes with (rather than replaces) this rule's vertical gap. */
286	  .article-body :global(.ping-section) {
287	    padding-top: var(--ping-section-gap);
288	    padding-bottom: var(--ping-section-gap);
289	  }
290	
291	  .article-body :global(.ping-section:first-child) {
292	    padding-top: 0;
293	  }
294	
295	  /* "The problem" gets a plain 1px stroke outline and its own left/right
296	     inset (on top of the padding-top/-bottom every section already has
297	     from the rule above) — the one section styled as a bordered card
298	     rather than a plain full-bleed block. padding-top/-bottom here
299	     re-declare --ping-section-gap (the FIXED token), not
300	     --ping-card-padding (the responsive one) — using the responsive
301	     variable for the vertical sides was the exact bug this replaced:
302	     it made this section's vertical gap shrink along with its horizontal
303	     inset on mobile, instead of staying fixed like every other section's. */
304	  .article-body :global(.ping-section--problem) {
305	    border: 1px solid var(--section-border-color);
306	    border-radius: 0.75rem; /* 12px */
307	    padding-top: var(--ping-section-gap);
308	    padding-bottom: var(--ping-section-gap);
309	    padding-left: var(--ping-card-padding);
310	    padding-right: var(--ping-card-padding);
311	    margin-top: var(--ping-card-padding);
312	    margin-bottom: var(--ping-card-padding);
313	  }
314	
315	  /* "The approach" gets the same left/right inset, matching "The problem"
316	     above — vertical padding stays on the fixed --ping-section-gap for
317	     the same reason. position: relative gives the ::after grid layer
318	     below a containing block to size itself against. Unlike "The problem",
319	     this section stays borderless/full-bleed on purpose — the border is
320	     what marks Problem as the one "card" section, and adding one here
321	     would blur that distinction. No overflow: hidden here (unlike the
322	     original version of this rule) — the ::after grid layer below is
323	     deliberately wider than this section's own box (it bleeds 40px past
324	     the left/right edges), and clipping at the section boundary would
325	     hide exactly that bleed. The page-level overflow-x-hidden on <body>
326	     (BaseLayout.astro) is what stops that bleed from ever causing a
327	     horizontal scrollbar on narrow viewports. */
328	  .article-body :global(.ping-section--approach) {
329	    position: relative;
330	    padding-top: var(--ping-section-gap);
331	    padding-bottom: var(--ping-section-gap);
332	    padding-left: var(--ping-card-padding);
333	    padding-right: var(--ping-card-padding);
334	  }
335	
336	  /* Decorative dot-grid background for "The approach". A single tiled
337	     radial-gradient draws a 1px dot every 24px using the same weak
338	     --section-border-color hairline already used for "The problem"'s
339	     outline, so it reads as part of this design system rather than a
340	     borrowed effect. (An earlier version of this used a two-axis
341	     repeating-linear-gradient line grid, matching aphera.co's reference;
342	     swapped to dots after finding a closer reference. A per-project
343	     accent-color tint was also tried and reverted — read as too loud/
344	     colorful for this background texture even at 25% strength; the
345	     neutral hairline color works better.)
346	     Deliberately ::after, not ::before: generated content always paints
347	     after an element's real children by spec, so ::after guarantees this
348	     stays behind the section's images/copy without depending on z-index
349	     stacking order against the LightboxImage markup (which has its own
350	     position: relative wrapper). The negative z-index below is
351	     belt-and-suspenders on top of that. Also inert to pointer/click
352	     interaction. Starts fully transparent — observeGridReveal()
353	     (src/lib/animations.ts) adds .grid-active via IntersectionObserver
354	     once the section scrolls into view, which is what actually plays the
355	     gridSequence fade (defined in global.css). */
356	  .article-body :global(.ping-section--approach::after) {
357	    content: "";
358	    position: absolute;
359	    /* Bleeds the grid 40px past the section's own left/right edges (top/bottom
360	       stay flush) so it reads as wider than the text column above it, similar
361	       to aphera.co's reference. This section has no overflow: hidden of its
362	       own (unlike "The problem"/"The solution") specifically so this bleed
363	       isn't clipped — the page-level overflow-x-hidden on <body>
364	       (BaseLayout.astro) is what stops it from ever causing a horizontal
365	       scrollbar on narrow viewports instead. */
366	    inset: 0 -40px;
367	    /* "1px, transparent 1px" (not "0, transparent 1px") is what makes a
368	       crisp dot instead of a soft blurred blob — the color stays solid from
369	       center out to the 1px radius, then cuts hard to transparent at that
370	       same radius. */
371	    background-image: radial-gradient(
372	      circle,
373	      var(--section-border-color) 1px,
374	      transparent 1px
375	    );
376	    background-size: 24px 24px;
377	    /* Fades the grid out near all four edges instead of cutting off hard
378	       — two gradients (one per axis) multiplied together via
379	       mask-composite: intersect, so a point only stays fully opaque where
380	       BOTH the horizontal and vertical fade are opaque (i.e. away from
381	       every edge at once). -webkit- variants are Safari's still-required
382	       prefixed equivalents (mask-composite ergo is broadly supported
383	       unprefixed now, but -webkit-mask-composite uses different keyword
384	       values, hence "source-in" there vs "intersect" above). */
385	    mask-image:
386	      linear-gradient(
387	        to right,
388	        transparent 0%,
389	        rgba(0, 0, 0, 1) 10%,
390	        rgba(0, 0, 0, 1) 90%,
391	        transparent 100%
392	      ),
393	      linear-gradient(
394	        to bottom,
395	        transparent 0%,
396	        rgba(0, 0, 0, 1) 10%,
397	        rgba(0, 0, 0, 1) 90%,
398	        transparent 100%
399	      );
400	    mask-composite: intersect;
401	    -webkit-mask-image:
402	      linear-gradient(
403	        to right,
404	        transparent 0%,
405	        rgba(0, 0, 0, 1) 10%,
406	        rgba(0, 0, 0, 1) 90%,
407	        transparent 100%
408	      ),
409	      linear-gradient(
410	        to bottom,
411	        transparent 0%,
412	        rgba(0, 0, 0, 1) 10%,
413	        rgba(0, 0, 0, 1) 90%,
414	        transparent 100%
415	      );
416	    -webkit-mask-composite: source-in;
417	    pointer-events: none;
418	    z-index: -1;
419	    opacity: 0;
420	  }
421	
422	  .article-body :global(.ping-section--approach.grid-active::after) {
423	    animation: gridSequence 1.4s ease-out forwards;
424	  }
425	
426	  /* "The solution" gets a translucent border and a subtle vertical-fade
427	     background, both tinted by the project's own --icon-color (set inline
428	     in the MDX, resolved the same way the headline accent and Postscript's
429	     divider already do) — so each case study gets a matching treatment in
430	     its own accent color instead of every project showing Ping's red.
431	     color-mix() against transparent is what lets a var()-sourced color
432	     carry a percentage opacity — CSS's plain `color / alpha%` syntax only
433	     accepts a literal color, not a custom property. */
434	  .article-body :global(.ping-section--solution) {
435	    border-radius: 0.75rem; /* 12px */
436	    padding-top: var(--ping-section-gap);
437	    padding-bottom: var(--ping-section-gap);
438	    padding-left: var(--ping-card-padding);
439	    padding-right: var(--ping-card-padding);
440	    margin-top: var(--ping-card-padding);
441	    margin-bottom: var(--ping-card-padding);
442	    border: 1px solid color-mix(in oklch, var(--icon-color) 50%, transparent);
443	    background: linear-gradient(
444	      0deg,
445	      color-mix(in oklch, var(--icon-color) 0%, transparent) 0%,
446	      color-mix(in oklch, var(--icon-color) 13%, transparent) 100%
447	    );
448	    background-origin: border-box;
449	    background-clip: padding-box, padding-box, border-box;
450	  }
451	
452	  /* A heading still sits close to the content directly under it (16px),
453	     same as Figma's "The problem"/"The approach" heading+paragraph groups —
454	     this is intra-section spacing, unaffected by the section padding above. */
455	  .article-body :global(h2 + *) {
456	    margin-top: 1rem; /* 16px */
457	  }
458	
459	  .article-body :global(h2) {
460	    font-family: var(--font-plex-sans);
461	    font-weight: 500;
462	    font-size: 1.5rem; /* 24px */
463	    line-height: 2.5rem; /* 40px */
464	    color: var(--portfolio-ink);
465	  }
466	
467	  .article-body :global(p) {
468	    font-family: var(--font-plex-sans);
469	    font-size: 1.125rem; /* 18px */
470	    line-height: 2rem; /* 32px */
471	    font-weight: 300;
472	  }
473	
474	  /* Paragraphs immediately following another paragraph (e.g. "The problem"'s
475	     three-paragraph run) sit tighter than the 40px inter-block gap above —
476	     Figma treats runs of body copy as one 16px-spaced group. */
477	  .article-body :global(p + p) {
478	    margin-top: 1rem; /* 16px */
479	  }
480	
481	  /* Every `.ping-section` in Figma is a `flex flex-col gap-[40px]` —
482	     Intro's paragraphs vs. its image, Approach's copy vs. its two-image row,
483	     a Point's LabeledRow vs. its LoopVideo, all 40px apart regardless of
484	     element type. This is intra-section spacing between a section's direct
485	     children, distinct from `.ping-section`'s own 60px outer padding above.
486	     `:not(p)` keeps this from overriding the tighter 16px `p + p` run
487	     spacing below — a `p` following a `p` should stay at 16px, not jump to
488	     40px just because both happen to sit inside a `.ping-section`. */
489	  .article-body :global(.ping-section > * + *:not(p)) {
490	    margin-top: 2.5rem; /* 40px */
491	  }
492	
493	  .article-body :global(a) {
494	    color: inherit;
495	    text-decoration: underline;
496	    text-decoration-skip-ink: none;
497	    text-underline-position: from-font;
498	  }
499	
500	  /* ─── Case-study page: snap sections ─────────────────────────────────────── */
501	  /* Each section fills the screen and snaps to its top edge. `mandatory` makes
502	     the browser always settle on a section start, but a section taller than
503	     the screen (the deep dive) still scrolls freely inside; only once you
504	     reach its end does it ask for roughly half a screen more of scroll before
505	     it snaps forward to the next section — that's the "hump". Scoped with
506	     :has() so it only applies on pages that contain a case study. */
507	  :global(html:has([data-case-study])) {
508	    scroll-snap-type: y mandatory;
509	  }
510	  @media (prefers-reduced-motion: no-preference) {
511	    :global(html:has([data-case-study])) {
512	      scroll-behavior: smooth;
513	    }
514	    /* Hidden until the Overview entrance animation (lib/caseStudy.ts) reveals
515	       them, so they don't flash visible first. */
516	    :global([data-ov]) {
517	      opacity: 0;
518	    }
519	  }
520	  .case-section {
521	    scroll-snap-align: start;
522	    min-height: 100dvh;
523	    /* Top: room for the sticky header, plus the section chip bar on small
524	       screens (below lg, where the side nav is replaced by that bar). Bottom:
525	       room for the fixed action bar. */
526	    padding-top: 8.5rem;
527	    padding-bottom: 8rem;
528	  }
529	  @media (min-width: 64rem) {
530	    .case-section {
531	      padding-top: 7rem;
532	    }
533	  }
534	
535	  /* The Overview is a full-width title slide, not part of the 900px reading
536	     column: from lg it stretches back across the side-nav gutter (the 300px
537	     margin cancels the grid's first column + gap) and centers its content in
538	     the full 1200px. Its content starts 160px down, as in Figma (56px page
539	     padding + 104px under the header row). */
540	  .case-section--overview {
541	    padding-top: 8rem;
542	    padding-bottom: 8rem;
543	  }
544	  @media (min-width: 64rem) {
545	    .case-section--overview {
546	      width: 1200px;
547	      margin-left: -300px;
548	      padding-top: 160px;
549	    }
550	  }
551	  /* Short laptop windows: pull the content up so the whole slide still fits. */
552	  @media (min-width: 64rem) and (max-height: 900px) {
553	    .case-section--overview {
554	      padding-top: 112px;
555	    }
556	  }
557	
558	  /* The side nav only belongs to the sections after the Overview: fade it out
559	     (and make it inert) while the Overview is showing. */
560	  [data-subnav-aside] {
561	    transition:
562	      opacity 0.3s ease-out,
563	      visibility 0.3s;
564	  }
565	  :global(body[data-section="overview"]) [data-subnav-aside] {
566	    opacity: 0;
567	    visibility: hidden;
568	    pointer-events: none;
569	  }
570	
571	  /* Jumping to a sub-item (e.g. #approach) shouldn't tuck it under the header. */
572	  .article-body :global([id]) {
573	    scroll-margin-top: 6rem;
574	  }
575	
576	  /* ─── Deep dive: lead paragraph and combined Problem + Solution card ───── */
577	  /* The opening paragraph of the intro is a larger lead-in, per the redesign. */
578	  .article-body :global(#intro > p:first-child) {
579	    font-size: 1.75rem; /* 28px */
580	    line-height: 2.5rem; /* 40px */
581	    font-weight: 400;
582	    color: var(--portfolio-ink);
583	  }
584	
585	  /* The problem and the solution now share one rounded card: the problem on a
586	     faint ink tint, the solution on the project-colored gradient below it. The
587	     two sections keep their own classes (and so their own styling); this wrapper
588	     only supplies the shared outline and clips their corners. */
589	  .article-body :global(.ps-card) {
590	    border: 1px solid var(--section-border-color);
591	    border-radius: 0.75rem; /* 12px */
592	    overflow: hidden;
593	    margin: var(--ping-card-padding) 0;
594	  }
595	  .article-body :global(.ps-card .ping-section--problem) {
596	    border: 0;
597	    border-radius: 0;
598	    margin: 0;
599	    background: color-mix(in oklch, var(--portfolio-ink) 4%, transparent);
600	  }
601	  .article-body :global(.ps-card .ping-section--solution) {
602	    border: 0;
603	    border-top: 1px solid
604	      color-mix(in oklch, var(--icon-color) 50%, transparent);
605	    border-radius: 0;
606	    margin: 0;
607	  }
608	</style>
