<div class="labeled-row flex w-full flex-col items-start gap-4">
  <p
    class="feature-title text-portfolio-ink m-0 flex w-full items-baseline gap-3 font-mono text-xl leading-7 font-medium"
  >
    <span class="feature-number shrink-0 text-sm leading-5"></span>
    <span class="min-w-0 flex-1">{label}</span>
  </p>
  <div
    class="font-plex-sans text-portfolio-ink/85 min-w-0 text-lg leading-7 font-normal [&_p]:mb-4 [&_p:last-child]:mb-0"
  >
    <slot />
  </div>
</div>

<style>
  .labeled-row {
    counter-increment: feature;
  }
  .feature-number {
    color: var(--icon-color);
  }
  .feature-number::before {
    content: counter(feature, decimal-leading-zero);
  }
</style>

---
// LoopVideo.astro — silent, looping, autoplaying inline video used to
// illustrate a case-study beat (Figma "Video" frame: 4px corners on a neutral
// surface, with a small "LOOP · 5S" tag in the top-left corner).
//
// The tag's length is read from the video itself once its metadata loads, so
// no one has to keep a hand-typed duration in sync with the file.
interface Props {
  webm: string;
  mp4: string;
  caption?: string;
}

const { webm, mp4, caption } = Astro.props;
---

<figure class="m-0 flex flex-col gap-4">
  <div class="loop-video relative overflow-hidden rounded-[4px]">
    <video class="block h-auto w-full" autoplay loop muted playsinline>
      <source src={webm} type="video/webm" />
      <source src={mp4} type="video/mp4" />
    </video>
    <span class="loop-tag" hidden>LOOP</span>
  </div>
  {
    caption && (
      <figcaption class="font-plex-sans text-portfolio-ink text-base leading-6">
        {caption}
      </figcaption>
    )
  }
</figure>

<style>
  .loop-video {
    background-color: color-mix(in srgb, var(--portfolio-ink) 8%, transparent);
  }
  /* A frosted cream chip with dark mono text, in both themes (it sits on top
     of the video, not the page). */
  .loop-tag {
    position: absolute;
    top: 8px;
    left: 8px;
    padding: 3px 8px;
    border-radius: 3px;
    background-color: rgba(255, 249, 242, 0.7);
    color: #18181b;
    font-family: var(--font-mono);
    font-size: 12px;
    font-weight: 500;
    line-height: 16px;
    white-space: nowrap;
  }
</style>

<script>
  // "LOOP · 5S" / "LOOP · 6.5S": whole seconds drop the decimal.
  function labelLoops() {
    document.querySelectorAll<HTMLElement>(".loop-video").forEach((box) => {
      const video = box.querySelector("video");
      const tag = box.querySelector<HTMLElement>(".loop-tag");
      if (!video || !tag || tag.dataset.ready) return;
      const apply = () => {
        if (!Number.isFinite(video.duration)) return;
        const secs = Math.round(video.duration * 2) / 2;
        tag.textContent = `LOOP · ${secs}S`;
        tag.hidden = false;
        tag.dataset.ready = "true";
      };
      if (video.readyState >= 1) apply();
      else video.addEventListener("loadedmetadata", apply, { once: true });
    });
  }
  document.addEventListener("astro:page-load", labelLoops);
</script>

---
// BeforeAfter.astro — the side-by-side comparison in "The approach" (Figma
// "Before / After"): two equal 276px-tall screenshots, each cropped to fit,
// with a mono caption underneath. The "After" label takes the project color.
import LightboxImage from "@/components/case-study/LightboxImage.astro";

interface Side {
  src: string;
  alt: string;
  label: string;
  caption: string;
}

interface Props {
  before: Side;
  after: Side;
}

const { before, after } = Astro.props;
---

<div class="before-after">
  {
    [
      { side: before, after: false },
      { side: after, after: true },
    ].map(({ side, after: isAfter }) => (
      <figure class="side">
        <LightboxImage src={side.src} alt={side.alt} flat />
        <figcaption>
          <span class:list={["label", isAfter && "label--after"]}>
            {side.label}
          </span>
          <span>{side.caption}</span>
        </figcaption>
      </figure>
    ))
  }
</div>

<style>
  .before-after {
    display: flex;
    flex-direction: column;
    gap: 16px;
  }
  @media (min-width: 40rem) {
    .before-after {
      flex-direction: row;
    }
  }
  .side {
    flex: 1 1 0;
    min-width: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  figcaption {
    display: flex;
    gap: 8px;
    font-family: var(--font-mono);
    font-size: 12px;
    line-height: 16px;
    text-transform: uppercase;
    color: var(--portfolio-muted);
    white-space: nowrap;
    overflow: hidden;
  }
  .label {
    font-weight: 600;
  }
  .label--after {
    color: var(--icon-color);
  }
</style>

