python3 - <<'EOF'
p='src/components/case-study/SubNav.astro'
s=open(p).read()
# stepped pill for the current top-level item
s=s.replace('''  .subnav-link[aria-current="true"] {
    background-color: var(--portfolio-nav-active);
    color: var(--portfolio-ink);
    font-weight: 600;
  }''','''  .subnav-link[aria-current="true"] {
    background-color: var(--portfolio-nav-active);
    color: var(--portfolio-ink);
    font-weight: 600;
    /* Figma's pill has stepped, pixel-style corners (6px deep, in 1.5 / 1.5 / 3px
       bands) rather than a smooth radius. */
    border-radius: 0;
    clip-path: polygon(
      6px 0,
      calc(100% - 6px) 0,
      calc(100% - 6px) 1.5px,
      calc(100% - 4px) 1.5px,
      calc(100% - 4px) 3px,
      calc(100% - 2px) 3px,
      calc(100% - 2px) 6px,
      100% 6px,
      100% calc(100% - 6px),
      calc(100% - 2px) calc(100% - 6px),
      calc(100% - 2px) calc(100% - 3px),
      calc(100% - 4px) calc(100% - 3px),
      calc(100% - 4px) calc(100% - 1.5px),
      calc(100% - 6px) calc(100% - 1.5px),
      calc(100% - 6px) 100%,
      6px 100%,
      6px calc(100% - 1.5px),
      4px calc(100% - 1.5px),
      4px calc(100% - 3px),
      2px calc(100% - 3px),
      2px calc(100% - 6px),
      0 calc(100% - 6px),
      0 6px,
      2px 6px,
      2px 3px,
      4px 3px,
      4px 1.5px,
      6px 1.5px
    );
  }''')
i=s.index('  /* Tree connector')
j=s.index('  /* Current sub-item')
s=s[:i]+'''  /* Tree connector (Figma: a 1px line at x=13, with a rounded elbow leading into
     each sub-item). The line runs from just inside the first item to where the
     last elbow starts; each elbow is a 12px box with a left and bottom edge. */
  .subnav-tree::before {
    content: "";
    position: absolute;
    left: 13px;
    top: 2px;
    bottom: 29px;
    width: 1px;
    background: var(--subnav-line);
  }
  .subnav-sublink {
    position: relative;
    padding-left: 2rem;
  }
  .subnav-sublink::before {
    content: "";
    position: absolute;
    left: 13px;
    top: 5px;
    width: 12px;
    height: 12.5px;
    border-left: 1px solid var(--subnav-line);
    border-bottom: 1px solid var(--subnav-line);
    border-bottom-left-radius: 4px;
  }
'''+s[j:]
s=s.replace('''  .subnav {
    display: flex;''','''  .subnav {
    --subnav-line: color-mix(in srgb, var(--portfolio-ink) 85%, transparent);
    display: flex;''')
open(p,'w').write(s)
EOF
echo ok

