file.content:
---
// BottomNav.astro — persistent bar of context-aware actions along the bottom
// of the viewport. Each page decides which actions it offers by passing an
// `actions` list to BaseLayout; this component just renders them as
// ActionButtons. The pages that shouldn't have it (start, about) pass none,
// and BaseLayout skips rendering this component entirely.
import ActionButton from "@/components/ActionButton.astro";

export interface NavAction {
  label: string;
  // Shorter label for narrow screens.
  shortLabel?: string;
  // Keyboard key that triggers the action: "enter", "esc", or a single letter.
  shortcut: string;
  href: string;
  // Dimmed text after the label (e.g. the next project's name).
  detail?: string;
  // Render filled at rest (the page's primary action).
  featured?: boolean;
  // Only show while one of these case-study sections is active (space
  // separated ids in the DOM). Omit to always show. The case-study script
  // toggles the `hidden` attribute as the reader scrolls.
  sections?: string[];
}

interface Props {
  actions: NavAction[];
}

const { actions } = Astro.props;
---

<nav
  aria-label="Page actions"
  class="bottom-nav pointer-events-none fixed inset-x-0 bottom-0 z-40 pt-10 pb-5 sm:pb-[58px]"
>
  <div
    style="max-width: calc(var(--page-max) + 3rem);"
    class="bottom-actions pointer-events-auto mx-auto flex w-full items-center gap-x-2 overflow-x-auto px-6 sm:gap-x-[var(--bottom-gap,1.5rem)] lg:pl-[calc(1.5rem+var(--bottom-gutter,var(--page-gutter)))]"
  >
    {
      actions.map((action) => (
        <ActionButton
          label={action.label}
          shortLabel={action.shortLabel}
          detail={action.detail}
          shortcut={action.shortcut}
          href={action.href}
          featured={action.featured}
          shape={action.featured ? "pill" : "rounded"}
          data-sections={action.sections?.join(" ")}
          hidden={
            action.sections ? !action.sections.includes("overview") : undefined
          }
        />
      ))
    }
  </div>
</nav>

<style>
  /* One row, never wrapping: on phones with several actions it scrolls
     sideways instead of stacking up over the page content. */
  .bottom-actions {
    scrollbar-width: none;
  }
  /* The left inset changes between case-study sections; slide rather than jump. */
  @media (prefers-reduced-motion: no-preference) {
    .bottom-actions {
      transition: padding-left 0.35s cubic-bezier(0.22, 1, 0.36, 1);
    }
  }
  /* If a row is still wider than the screen, fade its right edge as a hint
     that it scrolls. (When everything fits, the fade lands on empty padding.) */
  @media (max-width: 39.99rem) {
    .bottom-actions {
      mask-image: linear-gradient(
        to right,
        black calc(100% - 2rem),
        transparent
      );
    }
  }
  .bottom-actions::-webkit-scrollbar {
    display: none;
  }
  /* A soft fade behind the bar so page content scrolling underneath it
     doesn't collide with the button labels. The gradient only paints the
     bar's own padding area; the middle of the viewport stays untouched. */
  .bottom-nav {
    background-image: linear-gradient(
      to top,
      var(--portfolio-bg) 40%,
      transparent
    );
  }
</style>

content.content:
1	---
2	// TopNav.astro — site-wide header, shown on every page except the start page.
3	//
4	// Left:  Projects / About. The current section is bold + ink-colored and gets
5	//        aria-current="page".
6	// Right: a live local date + time, links to GitHub, Discord and LinkedIn, and
7	//        the theme toggle (moon in dark mode, sun in light mode) at the far end.
8	//
9	// The <header> below has `transition:persist`, so its DOM survives
10	// client-side navigations (no flicker, the clock keeps ticking). Because the
11	// server-rendered "current" state would then go stale, a small script below
12	// re-computes aria-current on every navigation.
13	import { GitBranch } from "pixelarticons/react/GitBranch";
14	import { User } from "pixelarticons/react/User";
15	import { MoonStar } from "pixelarticons/react/MoonStar";
16	import { Sun } from "pixelarticons/react/Sun";
17	import SocialLinks from "@/components/SocialLinks.astro";
18	import { ABOUT_HREF, PROJECTS_HREF } from "@/data/links";
19	
20	const pathname = Astro.url.pathname;
21	const section = pathname.startsWith(ABOUT_HREF) ? "about" : "projects";
22	
23	const navItems = [
24	  { id: "projects", label: "Projects", href: PROJECTS_HREF, Icon: GitBranch },
25	  { id: "about", label: "About", href: ABOUT_HREF, Icon: User },
26	];
27	---
28	
29	<header
30	  transition:persist="top-nav"
31	  style="max-width: calc(var(--page-max) + 3rem);"
32	  class="top-nav sticky top-0 z-50 mx-auto h-20 w-full px-6 pt-[var(--nav-top)]"
33	>
34	  <!-- The inner row is inset by the page gutter (see "Page grid" in global.css),
35	       so the nav starts at the same x as the page content, as in Figma. -->
36	  <div
37	    class="flex h-6 items-center justify-between gap-4 lg:pl-[var(--page-gutter)]"
38	  >
39	    <nav aria-label="Primary" class="flex items-center gap-6">
40	      {
41	        navItems.map(({ id, label, href, Icon }) => (
42	          <a
43	            href={href}
44	            data-nav={id}
45	            aria-current={section === id ? "page" : undefined}
46	            class="top-nav-item text-portfolio-muted flex items-center gap-3 font-mono text-sm"
47	          >
48	            <Icon width={24} height={24} />
49	            <span>{label}</span>
50	          </a>
51	        ))
52	      }
53	    </nav>
54	
55	    <!-- Date/time, social links, then the theme toggle at the far right. -->
56	    <div class="flex items-center gap-4">
57	      <!-- Filled in by the script below. min-w reserves the width so the
58	           icons next to it don't shift when the text first appears. Hidden on
59	           phones, where there isn't room for it beside the icons. -->
60	      <time
61	        data-clock
