180	      if (y > lastY && y > 120) header.setAttribute("data-hidden", "");
181	      else header.removeAttribute("data-hidden");
182	      lastY = y;
183	    },
184	    { passive: true },
185	  );
186	
187	  // ─── Active nav item ─────────────────────────────────────────────────────
188	  // Runs on first load and after every client-side navigation.
189	  document.addEventListener("astro:page-load", () => {
190	    const current = location.pathname.startsWith("/about")
191	      ? "about"
192	      : "projects";
193	    document.querySelectorAll<HTMLElement>("[data-nav]").forEach((el) => {
194	      if (el.dataset.nav === current) {
195	        el.setAttribute("aria-current", "page");
196	      } else {
197	        el.removeAttribute("aria-current");
198	      }
199	    });
200	  });
201	</script>
