1	---
2	// about.astro — the About page: a big "Hi, I'm Cody" hero, a side nav that
3	// follows the reader down the page, and four sections (About me, How I work,
4	// Work history, Elsewhere). The copy lives in src/data/about.ts. This page has
5	// no bottom nav, by design.
6	import { getCollection } from "astro:content";
7	import BaseLayout from "@/layouts/BaseLayout.astro";
8	import ProjectRow from "@/components/ProjectRow.astro";
9	import SectionNav from "@/components/about/SectionNav.astro";
10	import MobileSectionBar from "@/components/MobileSectionBar.astro";
11	import { projectIconMap } from "@/lib/projectIconMap";
12	import { Github } from "pixelarticons/react/Github";
13	import { Discord } from "pixelarticons/react/Discord";
14	import { Linkedin2 } from "pixelarticons/react/Linkedin2";
15	import { DISCORD_URL, GITHUB_URL, LINKEDIN_URL } from "@/data/links";
16	import { facts, howIWork, intro, sections, workHistory } from "@/data/about";
17	
18	// Look up each case study once so the work-history rows can use its name,
19	// icon, and colors.
20	const projects = new Map(
21	  (await getCollection("projects")).map((p) => [p.id, p]),
22	);
23	
24	const elsewhere = [
25	  { label: "GitHub", href: GITHUB_URL, Icon: Github, color: "#4183C4" },
26	  { label: "Discord", href: DISCORD_URL, Icon: Discord, color: "#5865F2" },
27	  { label: "LinkedIn", href: LINKEDIN_URL, Icon: Linkedin2, color: "#0077B5" },
28	];
29	---
30	
31	<BaseLayout
32	  title="About"
33	  description="Cody Keisler is a design engineer in Rock Hill, SC who designs directly in code."
34	>
35	  <div
36	    class="mx-auto flex w-full max-w-[1200px] flex-col gap-16 px-6 pb-32 lg:gap-20"
37	  >
38	    <!-- Hero -->
39	    <h1
40	      data-animate
41	      class="about-hero font-redaction text-portfolio-ink m-0 flex flex-nowrap items-center justify-center gap-x-[0.12em] pt-4 text-center font-normal"
42	    >
43	      <span>Hi, I’m</span>
44	      <span class="about-hero-name italic">Cody</span>
45	      <span
46	        role="img"
47	        aria-label="Pixel-art portrait of Cody"
48	        class="about-portrait bg-portfolio-ink"></span>
49	    </h1>
50	
51	    <div class="lg:grid lg:grid-cols-[260px_minmax(0,900px)] lg:gap-10">
52	      <!-- Small screens: a row of chips instead of the side nav. -->
53	      <MobileSectionBar items={sections} navAttr="data-section-nav" inFlow />
54	
55	      <!-- Side nav: sticky, shown from the lg breakpoint up. -->
56	      <aside class="hidden lg:block">
57	        <div class="sticky top-28">
58	          <SectionNav sections={sections} />
59	        </div>
60	      </aside>
61	
62	      <div class="flex min-w-0 flex-col gap-24">
63	        <!-- About me -->
64	        <section
65	          id="about-me"
66	          data-animate
67	          class="flex scroll-mt-28 flex-col gap-8"
68	        >
69	          <p
70	            class="font-plex-sans text-portfolio-ink max-w-[45rem] text-xl leading-[30px]"
71	          >
72	            {intro.lead}
73	          </p>
74	          <p
75	            class="font-plex-sans text-portfolio-ink/85 max-w-[45rem] text-lg leading-7"
76	          >
77	            {intro.body}
78	          </p>
79	
80	          <dl class="m-0 flex flex-col gap-4 pt-4">
81	            <div class="fact-row">
82	              <dt class="fact-label">Role</dt>
83	              <dd class="fact-value">{facts.role}</dd>
84	            </div>
85	            <div class="fact-row">
86	              <dt class="fact-label">Based in</dt>
87	              <dd class="m-0 flex min-w-0 flex-col gap-3">
88	                <span class="fact-value">{facts.basedIn}</span>
89	                <!-- Map. Stand-in dot-matrix pattern until the real map graphic
90	                     is added; swap the contents of .map-frame for it. -->
91	                <div
92	                  class="map-frame"
93	                  role="img"
94	                  aria-label="Map of Rock Hill, SC"
95	                >
96	                </div>
97	              </dd>
98	            </div>
99	            <div class="fact-row">
100	              <dt class="fact-label">Focus</dt>
101	              <dd class="fact-value">{facts.focus}</dd>
102	            </div>
103	          </dl>
104	        </section>
105	
106	        <!-- How I work -->
107	        <section id="how-i-work" class="flex scroll-mt-28 flex-col">
108	          <h2 class="section-eyebrow pb-6">How I work</h2>
109	          {
110	            howIWork.map((item, index) => (
111	              <div class="work-row">
112	                <p class="text-portfolio-accent m-0 font-mono text-sm sm:w-10 sm:shrink-0">
113	                  {String(index + 1).padStart(2, "0")}
114	                </p>
115	                <div class="flex min-w-0 flex-col gap-2">
116	                  <p class="text-portfolio-ink m-0 font-mono text-lg font-medium">
117	                    {item.title}
118	                  </p>
119	                  <p class="font-plex-sans text-portfolio-ink/85 m-0 text-lg leading-7">
120	                    {item.body}
121	                  </p>
122	                </div>
123	              </div>
124	            ))
125	          }
126	        </section>
127	
128	        <!-- Work history -->
129	        <section id="work-history" class="flex scroll-mt-28 flex-col gap-6">
130	          <h2 class="section-eyebrow">Work history</h2>
131	          <div class="flex flex-col">
132	            {
133	              workHistory.map((company) => (
134	                <div class="company">
135	                  <div class="history-grid items-center">
136	                    <p class="text-portfolio-accent m-0 font-mono text-sm uppercase">
137	                      {company.tenure}
138	                    </p>
139	                    <div class="flex items-center gap-[14px]">
140	                      <span class="logo-tile" aria-hidden="true">
141	                        {company.logo ? (
142	                          <img
143	                            src={company.logo}
144	                            alt=""
145	                            class="size-full object-cover"
146	                          />
147	                        ) : (
148	                          company.name.charAt(0)
149	                        )}
150	                      </span>
151	                      <h3 class="font-plex-sans text-portfolio-ink m-0 text-xl font-normal">
152	                        {company.name}
153	                      </h3>
154	                    </div>
155	                  </div>
156	
157	                  <div class="flex flex-col gap-6">
158	                    {company.roles.map((role) => (
159	                      <div class="history-grid items-baseline">
160	                        <p class="fact-label m-0 leading-[22px]">
161	                          {role.dates}
162	                        </p>
163	                        <div class="flex min-w-0 flex-col gap-3">
164	                          <div class="flex flex-col gap-1.5">
165	                            <p class="font-plex-sans text-portfolio-ink m-0 text-base leading-[22px] font-medium">
166	                              {role.title}
167	                            </p>
168	                            {role.description && (
169	                              <p class="font-plex-sans text-portfolio-ink/80 m-0 text-base leading-6">
170	                                {role.description}
171	                              </p>
172	                            )}
173	                          </div>
