1	---
2	// about.astro — the About page: a big "Hi, I'm Cody" hero, a side nav that
3	// follows the reader down the page, and four sections (About me, How I work,
4	// Work history, Elsewhere). The copy lives in src/data/about.ts. This page has
5	// no bottom nav, by design.
6	import { getCollection } from "astro:content";
7	import BaseLayout from "@/layouts/BaseLayout.astro";
8	import ProjectRow from "@/components/ProjectRow.astro";
9	import SectionNav from "@/components/about/SectionNav.astro";
10	import MobileSectionBar from "@/components/MobileSectionBar.astro";
11	import { projectIconMap } from "@/lib/projectIconMap";
