15	import { DISCORD_URL, GITHUB_URL, LINKEDIN_URL } from "@/data/links";
16	import { facts, howIWork, intro, sections, workHistory } from "@/data/about";
17	
18	// Look up each case study once so the work-history rows can use its name,
19	// icon, and colors.
20	const projects = new Map(
21	  (await getCollection("projects")).map((p) => [p.id, p]),
22	);
23	
24	const elsewhere = [
25	  { label: "GitHub", href: GITHUB_URL, Icon: Github, color: "#4183C4" },
26	  { label: "Discord", href: DISCORD_URL, Icon: Discord, color: "#5865F2" },
