30	
31	<BaseLayout
32	  title="About"
33	  description="Cody Keisler is a design engineer in Rock Hill, SC who designs directly in code."
34	>
35	  <div
36	    class="mx-auto flex w-full max-w-[1200px] flex-col gap-16 px-6 pb-32 lg:gap-20"
