163	                        <div class="flex min-w-0 flex-col gap-3">
164	                          <div class="flex flex-col gap-1.5">
165	                            <p class="font-plex-sans text-portfolio-ink m-0 text-base leading-[22px] font-medium">
166	                              {role.title}
167	                            </p>
168	                            {role.description && (
169	                              <p class="font-plex-sans text-portfolio-ink/80 m-0 text-base leading-6">
