185	                                    icon={projectIconMap[d.icon]}
186	                                    iconColor={d.iconColor}
187	                                    iconColorDark={d.iconColorDark}
188	                                    badgeColor={d.badgeColor}
189	                                    badgeColorDark={d.badgeColorDark}
190	                                  />
191	                                );
192	                              })}
193	                            </div>
194	                          )}
195	                        </div>
196	                      </div>
197	                    ))}
198	                  </div>
199	                </div>
200	              ))
201	            }
202	          </div>
203	        </section>
204	
205	        <!-- Elsewhere -->
206	        <section id="elsewhere" class="flex scroll-mt-28 flex-col gap-6">
207	          <h2 class="section-eyebrow">Elsewhere</h2>
208	          <div class="flex flex-wrap gap-4">
