213	                  target="_blank"
214	                  rel="noopener noreferrer"
215	                  class="elsewhere-pill text-portfolio-ink flex items-center gap-2 rounded-full py-2 pr-3.5 pl-3 font-mono text-sm font-medium"
216	                >
217	                  <span style={{ color }} class="flex">
218	                    <Icon width={16} height={16} />
219	                  </span>
220	                  {label}
