222	              ))
223	            }
224	          </div>
225	        </section>
226	      </div>
227	    </div>
228	  </div>
229	</BaseLayout>
230	
231	<style>
232	  /* ─── Hero ─────────────────────────────────────────────────────────────── */
233	  /* 156px at desktop widths, scaling down with the viewport; every child is
234	     sized in em so the portrait stays in proportion to the lettering. */
235	  .about-hero {
236	    font-size: clamp(2.5rem, 1rem + 9.5vw, 9.75rem);
237	    line-height: 1;
238	    letter-spacing: -0.02em;
239	  }
240	  /* "Cody" is filled with a teal -> blue -> purple gradient. The text itself
241	     is made transparent and the gradient is clipped to its letterforms. */
242	  .about-hero-name {
243	    background-image: linear-gradient(
244	      90deg,
245	      #40c6b0 0%,
246	      #4f9cf0 55%,
247	      #8b6cf5 100%
248	    );
249	    -webkit-background-clip: text;
250	    background-clip: text;
251	    color: transparent;
252	    /* Room for the italic's overhang so the gradient doesn't clip the "y". */
253	    padding-right: 0.08em;
254	  }
255	  /* The pixel portrait is a single-color SVG, so it's drawn as a mask over an
256	     ink-colored box to follow the theme (same technique as the start page).
257	     The negative margin tucks it against the end of "Cody", as in Figma. */
258	  .about-portrait {
259	    width: 1.08em;
260	    height: 1.08em;
261	    margin-left: -0.28em;
