313	    font-family: var(--font-mono);
314	    font-size: 0.875rem;
315	    font-weight: 400;
316	    text-transform: uppercase;
317	    color: var(--portfolio-muted);
318	  }
319	
320	  /* One numbered "How I work" principle: hairline on top, number + text. */
