333	    }
334	  }
335	
336	  /* ─── Work history ─────────────────────────────────────────────────────── */
337	  .company {
338	    display: flex;
339	    flex-direction: column;
340	    gap: 1.5rem;
341	    padding: 1.5rem 0;
342	    border-top: 1px solid
