1	---
2	// SectionNav.astro — the About page's side nav: one link per section, with the
3	// section currently in view highlighted. Same idea as the case study's SubNav
4	// but flat (no sub-items) and a touch larger, per the Figma About frame.
5	// The script at the bottom watches scrolling and sets aria-current.
6	interface Props {
7	  sections: { id: string; label: string }[];
8	}
9	
10	const { sections } = Astro.props;
11	---
12	
13	<nav
14	  aria-label="About sections"
15	  data-section-nav
16	  class="flex w-[260px] flex-col gap-2 font-mono text-base"
17	>
18	  {
19	    sections.map((section, index) => (
20	      <a
21	        href={`#${section.id}`}
22	        data-section-link={section.id}
23	        aria-current={index === 0 ? "true" : "false"}
24	        class="section-link"
25	      >
26	        {section.label}
27	      </a>
28	    ))
29	  }
30	</nav>
31	
32	<style>
33	  .section-link {
34	    display: block;
35	    padding: 0.6875rem 1.25rem; /* 11px / 20px: a 44px-tall row, as in Figma */
36	    border-radius: 0.5rem;
37	    color: var(--portfolio-muted);
38	    transition:
39	      background-color 0.2s ease-out,
40	      color 0.2s ease-out;
41	  }
42	  .section-link:hover {
43	    color: var(--portfolio-ink);
44	  }
45	  .section-link:focus {
46	    outline: none;
47	  }
48	  .section-link:focus-visible {
49	    outline: 2px solid var(--portfolio-ink);
50	    outline-offset: -2px;
51	  }
52	  .section-link[aria-current="true"] {
53	    background-color: var(--portfolio-nav-active);
54	    color: var(--portfolio-ink);
55	  }
56	  @media (prefers-reduced-motion: reduce) {
57	    .section-link {
58	      transition: none;
59	    }
60	  }
61	</style>
62	
63	<script>
64	  // Highlights the link for whichever section covers a line ~35% down the
65	  // viewport. Runs on first load and after each client-side navigation; the
66	  // scroll listener is removed through an AbortController so it can't stack.
67	  let controller: AbortController | null = null;
68	
69	  document.addEventListener("astro:page-load", () => {
70	    controller?.abort();
71	    controller = null;
72	
73	    const links = [
74	      ...document.querySelectorAll<HTMLElement>(
75	        "[data-section-nav] [data-section-link]",
76	      ),
77	    ];
78	    if (links.length === 0) return;
79	
80	    const sections = links
81	      .map((link) => document.getElementById(link.dataset.sectionLink ?? ""))
82	      .filter((el): el is HTMLElement => el !== null);
83	
84	    controller = new AbortController();
85	    let queued = false;
86	
87	    function update() {
88	      const line = window.innerHeight * 0.35;
89	      // The last section whose top has crossed the line is "current".
90	      let current = sections[0];
91	      for (const section of sections) {
92	        if (section.getBoundingClientRect().top <= line) current = section;
93	      }
94	      // At the very bottom of the page the last section should win even if
95	      // it's too short to ever reach the line.
96	      const atBottom =
97	        window.innerHeight + window.scrollY >= document.body.scrollHeight - 4;
98	      if (atBottom) current = sections[sections.length - 1];
99	
100	      links.forEach((link) => {
101	        const isCurrent = link.dataset.sectionLink === current?.id;
102	        link.setAttribute("aria-current", String(isCurrent));
103	        // In the mobile chip bar, slide the row so the current chip stays in
104	        // view (scrolling the bar itself, never the page).
105	        const bar = link.closest<HTMLElement>(".mobile-bar");
106	        if (isCurrent && bar) {
107	          bar.scrollTo({
108	            left: link.offsetLeft - (bar.clientWidth - link.offsetWidth) / 2,
109	            behavior: "smooth",
110	          });
111	        }
112	      });
113	    }
114	
115	    window.addEventListener(
116	      "scroll",
117	      () => {
118	        if (queued) return;
119	        queued = true;
120	        requestAnimationFrame(() => {
121	          queued = false;
122	          update();
123	        });
124	      },
125	      { passive: true, signal: controller.signal },
126	    );
127	    update();
128	  });
129	</script>
130

