content.content:
import type { NavAction } from "@/layouts/BottomNav.astro";

interface Props {
  title: string;
  description?: string;
  // Which page layout this is. Sets `data-page` on <body>, which global.css
  // uses to size the page column and gutter that the nav and content share.
  page?: "home" | "case-study" | "about";
  // Which section of the page is showing at first (case study only): sets
  // `data-section` on <body> so the nav geometry can differ per section. The
  // case-study script keeps it up to date as the reader scrolls.
  section?: string;
  // Hide the top nav (the start page has its own full-screen layout).
  hideTopNav?: boolean;
  // Actions for the persistent bottom bar. Omit (or pass none) for pages
   gutter only exists from the lg breakpoint up; below that, pages are a single
   column and the gutter is 0. */
:root {
  --page-max: 1200px;
  --page-gutter: 0px;
  /* Space above the nav row inside the 80px sticky header: Figma puts the nav
     41px down on the Projects page and 56px down on the other pages. */
  --nav-top: 41px;
}
@media (min-width: 64rem) {
  /* Home / Projects: 990px column, 176px gutter (152px label column + 24px gap). */
  body[data-page="home"] {
    --page-max: 990px;
    --page-gutter: 176px;
  }
}

@media (min-width: 64rem) {
  /* Case study: a 1200px column. Past the Overview, a 260px side nav + 40px gap
     fill the left gutter (300px) and the top nav starts after it; the bottom
     action bar starts 10px further in. On the Overview there's no side nav: the
     nav spans the full width and the action bar centers under the 900px body
     column (150px in, plus the same 10px). Changing section animates between
     the two (see the transitions on the nav). */
  body[data-page="case-study"] {
    --page-max: 1200px;
    --page-gutter: 300px;
    --bottom-gutter: 310px;
    --bottom-gap: 37px;
    --nav-top: 56px;
  }
  body[data-page="case-study"][data-section="overview"] {
    --page-gutter: 0px;
    --bottom-gutter: 160px;
  }
}

@layer base {
  html {
    @apply font-sans;

